class NetworkClient private constructor() {

    companion object {
        private const val BASE_URL = "https://api.service.example.com/v1/"
        private const val CONNECT_TIMEOUT = 10L
        private const val READ_TIMEOUT = 30L
        private const val WRITE_TIMEOUT = 30L

        @Volatile
        private var instance: NetworkClient? = null

        fun getInstance(context: Context): NetworkClient {
            return instance ?: synchronized(this) {
                instance ?: NetworkClient().also { instance = it }
            }
        }
    }

    private val okHttpClient: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(CONNECT_TIMEOUT, TimeUnit.SECONDS)
            .readTimeout(READ_TIMEOUT, TimeUnit.SECONDS)
            .writeTimeout(WRITE_TIMEOUT, TimeUnit.SECONDS)
            .addInterceptor { chain ->
                val request = chain.request().newBuilder()
                    .addHeader("Authorization", "Bearer ${getAuthToken()}")
                    .build()
                chain.proceed(request)
            }
            .build()
    }

    suspend fun <T> executeRequest(call: suspend () -> Response<T>): Result<T> {
        return try {
            val response = call()
            if (response.isSuccessful) {
                Result.success(response.body())
            } else {
                Result.failure(HttpException(response))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

